import random, time

N = 50
W = 7
G = 10
S = 5

def try_build(seed, time_limit=20):
    random.seed(seed)
    played = [set() for _ in range(N)]
    schedule = []
    start = time.time()

    def solve_week(w, groups, remaining):
        if time.time() - start > time_limit:
            return 'TIMEOUT'
        for gi in range(G):
            if len(groups[gi]) < S:
                if len(groups[gi]) == 0:
                    p = min(remaining)
                    groups[gi].append(p)
                    remaining.remove(p)
                    r = solve_week(w, groups, remaining)
                    if r: 
                        return r
                    remaining.add(p)
                    groups[gi].pop()
                    return False
                else:
                    cur = groups[gi]
                    cands = [p for p in remaining if not any(q in played[p] for q in cur)]
                    # heuristic: sort by number of constraints
                    random.shuffle(cands)
                    for p in cands:
                        groups[gi].append(p)
                        remaining.remove(p)
                        r = solve_week(w, groups, remaining)
                        if r == 'TIMEOUT': return r
                        if r: return True
                        remaining.add(p)
                        groups[gi].pop()
                    return False
        return True

    for w in range(W):
        if w == 0:
            groups = [[5*g + j for j in range(5)] for g in range(10)]
        else:
            groups = [[] for _ in range(G)]
            remaining = set(range(N))
            r = solve_week(w, groups, remaining)
            if r == 'TIMEOUT' or not r:
                return None
        schedule.append([list(g) for g in groups])
        for g in groups:
            for i in range(len(g)):
                for j in range(i+1,len(g)):
                    a,b = g[i],g[j]
                    played[a].add(b)
                    played[b].add(a)
    return schedule

result = None
for seed in range(50):
    t0 = time.time()
    s = try_build(seed, time_limit=5)
    elapsed = time.time()-t0
    if s:
        print(f"Seed {seed}: FOUND in {elapsed:.2f}s")
        result = s
        break
    else:
        print(f"Seed {seed}: Failed in {elapsed:.2f}s")

if result:
    # verify
    played = set()
    ok = True
    for w, weekgroups in enumerate(result):
        for g in weekgroups:
            assert len(g) == 5
            for i in range(5):
                for j in range(i+1,5):
                    p = (min(g[i],g[j]), max(g[i],g[j]))
                    if p in played:
                        print("DUP", p, "week", w)
                        ok = False
                    played.add(p)
    print("Valid:", ok)
    # build output
    out = [0]*(W*N)
    for w in range(W):
        for gi,grp in enumerate(result[w]):
            for p in grp:
                out[w*N + p] = gi
    print(out[:50])
    # save
    import json
    with open('/tmp/sol.json','w') as f: json.dump(out, f)

