# Let me try a smarter per-week solver: for each week, we need to partition 50 players into 10 groups of 5,
# where each group is an "independent set" in the played-graph (no two adjacent have played).
# This is an exact cover / graph coloring like problem.
# Use constraint propagation with best-heuristic.
# Actually, a smarter method: for each week use SAT.

# Alternative approach: use z3/pysat per-week.
from pysat.solvers import Cadical153
from pysat.card import CardEnc, EncType
from pysat.formula import IDPool
import time, random

N = 50
G = 10
S = 5

def solve_week(played_pairs, seed=0):
    """played_pairs: set of (p,q) with p<q already played. Return list of 10 groups."""
    vpool = IDPool()
    def x(p,g): return vpool.id(('x',p,g))
    solver = Cadical153()
    # each player in exactly one group
    for p in range(N):
        lits = [x(p,g) for g in range(G)]
        solver.add_clause(lits)
        for i in range(G):
            for j in range(i+1,G):
                solver.add_clause([-x(p,i), -x(p,j)])
    # each group exactly 5 players (use seqcounter)
    for g in range(G):
        lits = [x(p,g) for p in range(N)]
        cnf = CardEnc.equals(lits=lits, bound=S, vpool=vpool, encoding=EncType.seqcounter)
        for c in cnf.clauses: solver.add_clause(c)
    # no two played-together in same group
    for (p,q) in played_pairs:
        for g in range(G):
            solver.add_clause([-x(p,g), -x(q,g)])
    # symmetry: player 0 in group 0
    solver.add_clause([x(0,0)])
    if not solver.solve():
        return None
    model = set(solver.get_model())
    groups = [[] for _ in range(G)]
    for p in range(N):
        for g in range(G):
            if x(p,g) in model:
                groups[g].append(p)
                break
    solver.delete()
    return groups

def build_schedule(seed, W=7):
    random.seed(seed)
    played = set()
    schedule = []
    # Week 0: standard
    groups0 = [[5*g + j for j in range(5)] for g in range(10)]
    schedule.append(groups0)
    for g in groups0:
        for i in range(5):
            for j in range(i+1,5):
                played.add((g[i],g[j]))
    for w in range(1, W):
        t0 = time.time()
        g = solve_week(played)
        print(f"Week {w}: {time.time()-t0:.2f}s, {'ok' if g else 'FAIL'}")
        if not g:
            return None
        schedule.append(g)
        for grp in g:
            for i in range(5):
                for j in range(i+1,5):
                    a,b = sorted([grp[i],grp[j]])
                    played.add((a,b))
    return schedule

t0 = time.time()
s = build_schedule(0, W=7)
print("Total:", time.time()-t0)
if s:
    # verify
    pl = set()
    ok = True
    for w in range(7):
        for grp in s[w]:
